INSERT INTO `announcements` VALUES (1,1,'Nervous System Quiz – Due Tomorrow!','Please be reminded that the Nervous System Chapter Quiz is due tomorrow, May 12, 2025 at 11:59 PM. The quiz consists of 12 multiple choice questions with a 30-minute time limit.','quiz','all',1,1,'2026-05-11 15:43:29','2026-05-11 15:43:29'),(2,1,'New Module: Digestive System Now Available','The Digestive System module has been published with 4 sub-modules, 13 lessons, and 2 assessment activities. Explore the interactive 3D digestive tract model!','lesson','all',0,1,'2026-05-11 15:43:29','2026-05-11 15:43:29'),(3,1,'Science Fair Registrations Open','Registrations for the 2025 School Science Fair are now open. Submit your registration forms to Mrs. Reyes by May 20, 2025.','event','all',0,1,'2026-05-11 15:43:29','2026-05-11 15:43:29'),(4,1,'Nervous System Quiz – Due This Week','The Nervous System Chapter Quiz is now active and due in 3 days. Review your notes on the brain, spinal cord, neurons, and peripheral nervous system. The quiz has 10 questions and a 30-minute time limit.','quiz','all',0,1,'2026-09-05 11:45:21','2026-09-05 11:45:21'),(5,1,'Skeletal System Module Now Available','The complete Skeletal System module has been published. It includes reading materials, a 3D explorer activity, and a 10-question quiz. All Grade 10 students are expected to complete it by end of week.','lesson','all',0,1,'2026-09-05 11:45:21','2026-09-05 11:45:21'),(6,1,'Nervous System Quiz – Due This Week','The Nervous System Chapter Quiz is now active and due in 3 days. Review your notes on the brain, spinal cord, neurons, and peripheral nervous system. The quiz has 10 questions and a 30-minute time limit.','quiz','all',0,1,'2026-09-05 11:47:18','2026-09-05 11:47:18'),(7,1,'Skeletal System Module Now Available','The complete Skeletal System module has been published. It includes reading materials, a 3D explorer activity, and a 10-question quiz. All Grade 10 students are expected to complete it by end of week.','lesson','all',0,1,'2026-09-05 11:47:18','2026-09-05 11:47:18'),(8,1,'Nervous System Quiz – Due This Week','The Nervous System Chapter Quiz is now active and due in 3 days. Review your notes on the brain, spinal cord, neurons, and peripheral nervous system. The quiz has 10 questions and a 30-minute time limit.','quiz','all',0,1,'2026-09-05 11:48:00','2026-09-05 11:48:00'),(9,1,'Skeletal System Module Now Available','The complete Skeletal System module has been published. It includes reading materials, a 3D explorer activity, and a 10-question quiz. All Grade 10 students are expected to complete it by end of week.','lesson','all',0,1,'2026-09-05 11:48:00','2026-09-05 11:48:00'),(10,1,'Nervous System Quiz – Due This Week','The Nervous System Chapter Quiz is now active and due in 3 days. Review your notes on the brain, spinal cord, neurons, and peripheral nervous system. The quiz has 10 questions and a 30-minute time limit.','quiz','all',0,1,'2026-09-05 11:49:00','2026-09-05 11:49:00'),(11,1,'Skeletal System Module Now Available','The complete Skeletal System module has been published. It includes reading materials, a 3D explorer activity, and a 10-question quiz. All Grade 10 students are expected to complete it by end of week.','lesson','all',0,1,'2026-09-05 11:49:00','2026-09-05 11:49:00'),(12,1,'Nervous System Quiz – Due This Week','The Nervous System Chapter Quiz is now active and due in 3 days. Review your notes on the brain, spinal cord, neurons, and peripheral nervous system. The quiz has 10 questions and a 30-minute time limit.','quiz','all',0,1,'2026-09-05 11:49:19','2026-09-05 11:49:19'),(13,1,'Skeletal System Module Now Available','The complete Skeletal System module has been published. It includes reading materials, a 3D explorer activity, and a 10-question quiz. All Grade 10 students are expected to complete it by end of week.','lesson','all',0,1,'2026-09-05 11:49:19','2026-09-05 11:49:19'),(14,1,'Welcome to AnatomIQ – School Year 2024-2025','Welcome to our interactive anatomy learning system! All modules are now available. Start with the Skeletal System and work your way through all 9 body systems. Your progress will be tracked automatically.','general','all',1,1,'2026-09-05 11:52:52','2026-09-05 11:52:52'),(15,1,'Nervous System Quiz – Due This Week','The Nervous System Chapter Quiz is now active and due in 3 days. Review your notes on the brain, spinal cord, neurons, and peripheral nervous system. The quiz has 10 questions and a 30-minute time limit.','quiz','all',0,1,'2026-09-05 11:52:52','2026-09-05 11:52:52'),(16,1,'Skeletal System Module Now Available','The complete Skeletal System module has been published. It includes reading materials, a 3D explorer activity, and a 10-question quiz. All Grade 10 students are expected to complete it by end of week.','lesson','all',0,1,'2026-09-05 11:52:52','2026-09-05 11:52:52'),(17,1,'Test Automation Announcement','This announcement was created during automated verification.','general','all',1,1,'2026-09-05 11:54:02','2026-09-05 11:54:02'),(21,1,'Test','Test content','general','all',0,1,'2026-09-06 04:25:42','2026-09-06 04:25:42');
