INSERT INTO `body_systems` VALUES (1,'skeletal','Skeletal System','🦴','#f59e0b','The structural framework of the body, providing shape, support, and protection for vital organs.',1,1),(2,'muscular','Muscular System','💪','#ef4444','Over 600 muscles responsible for movement, posture maintenance, and heat production.',2,1),(3,'circulatory','Circulatory System','🫀','#dc2626','Transports blood, oxygen, nutrients, hormones, and waste products throughout the body.',3,1),(4,'respiratory','Respiratory System','🫁','#3b82f6','Enables gas exchange — taking in oxygen and expelling carbon dioxide via the lungs.',4,1),(5,'digestive','Digestive System','🥗','#10b981','Breaks down food into nutrients that can be absorbed and used for energy. Spans about 9 meters.',5,1),(6,'urinary','Urinary System','🫘','#f59e0b','Filters blood, removes metabolic waste, regulates fluid balance and blood pressure.',6,1),(7,'nervous','Nervous System','🧠','#8b5cf6','Coordinates body activities by transmitting signals using neurons. Contains ~86 billion nerve cells.',7,1),(8,'reproductive','Reproductive System','🌸','#ec4899','Responsible for sexual reproduction and production of sex hormones such as estrogen and testosterone.',8,1),(9,'endocrine','Endocrine System','⚗️','#14b8a6','Regulates body functions through hormones secreted directly into the bloodstream by glands.',9,1);
/*!40000 ALTER TABLE `body_systems` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `lessons`
--

DROP TABLE IF EXISTS `lessons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `lessons` (
  `lesson_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `module_id` int(10) unsigned NOT NULL,
  `teacher_id` int(10) unsigned NOT NULL,
  `title` varchar(200) NOT NULL,
  `lesson_type` enum('reading','video','3d_model','interactive','quiz_prep') NOT NULL DEFAULT 'reading',
  `content_text` longtext DEFAULT NULL,
  `media_url` varchar(255) DEFAULT NULL,
  `duration_mins` int(11) DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `status` enum('draft','published','archived') NOT NULL DEFAULT 'draft',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`lesson_id`),
  KEY `teacher_id` (`teacher_id`),
  KEY `idx_module` (`module_id`),
  CONSTRAINT `lessons_ibfk_1` FOREIGN KEY (`module_id`) REFERENCES `modules` (`module_id`) ON DELETE CASCADE,
  CONSTRAINT `lessons_ibfk_2` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=330 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

