INSERT INTO `questions` VALUES (101,1,'How many bones does the adult human skeleton have?','multiple_choice',NULL,NULL,1.00,1),(102,1,'Which is the longest and strongest bone in the human body?','multiple_choice',NULL,NULL,1.00,2),(103,1,'What is the primary mineral that makes bones hard?','multiple_choice',NULL,NULL,1.00,3),(104,1,'The ribcage is made up of how many pairs of ribs?','multiple_choice',NULL,NULL,1.00,4),(105,1,'Which type of bone cell is responsible for breaking down bone tissue?','multiple_choice',NULL,NULL,1.00,5),(106,1,'What is the smallest bone in the human body?','multiple_choice',NULL,NULL,1.00,6),(107,1,'Which part of the skeleton protects the brain?','multiple_choice',NULL,NULL,1.00,7),(108,1,'What type of joint allows rotation, such as the neck joint?','multiple_choice',NULL,NULL,1.00,8),(109,1,'The spine is made up of individual bones called:','multiple_choice',NULL,NULL,1.00,9),(110,1,'Which of the following is a function of the skeletal system?','multiple_choice',NULL,NULL,1.00,10),(111,2,'What is the largest and most complex part of the brain responsible for higher cognitive functions?','multiple_choice',NULL,NULL,1.00,1),(112,2,'Which part of the nervous system is responsible for the \"fight or flight\" response?','multiple_choice',NULL,NULL,1.00,2),(113,2,'Neurons transmit signals through specialized junctions called:','multiple_choice',NULL,NULL,1.00,3),(114,2,'The protective covering of neurons that speeds up nerve impulse transmission is called:','multiple_choice',NULL,NULL,1.00,4),(115,2,'Which of the following is NOT a function of the nervous system?','multiple_choice',NULL,NULL,1.00,5),(116,2,'How many pairs of cranial nerves originate from the brain?','multiple_choice',NULL,NULL,1.00,6),(117,2,'The cerebellum is primarily responsible for:','multiple_choice',NULL,NULL,1.00,7),(118,2,'What type of neuron carries signals FROM the CNS TO muscles?','multiple_choice',NULL,NULL,1.00,8),(119,2,'The space between two neurons where chemical signals cross is the:','multiple_choice',NULL,NULL,1.00,9),(120,2,'Which brain structure controls heart rate, breathing, and blood pressure?','multiple_choice',NULL,NULL,1.00,10),(121,4,'Click directly on the Left Ventricle on the anatomical diagram.','hotspot',NULL,'{\"target_label\":\"Left Ventricle\",\"target_id\":\"hotspot_left_ventricle\"}',2.00,1),(122,4,'Identify and click on the Right Ventricle chamber.','hotspot',NULL,'{\"target_label\":\"Right Ventricle\",\"target_id\":\"hotspot_right_ventricle\"}',2.00,2),(123,4,'Locate and pin the Left Atrium.','hotspot',NULL,'{\"target_label\":\"Left Atrium\",\"target_id\":\"hotspot_left_atrium\"}',2.00,3),(124,4,'Locate and pin the Right Atrium.','hotspot',NULL,'{\"target_label\":\"Right Atrium\",\"target_id\":\"hotspot_right_atrium\"}',2.00,4);
